sys_script.script:
(function executeRule(current, previous) {
      if (gs.nil(current.getValue('sync_filter_group'))) {
          gs.addErrorMessage('Sync Filter Group is required. Please select a group for this filter item.');
          current.setAbortAction(true);
          return;
      }

      // Validate: label_dimension is mandatory
      if (gs.nil(current.getValue('label_dimension'))) {
          gs.addErrorMessage('Label Dimension is required.');
          current.setAbortAction(true);
          return;
      }

      // Check for duplicate: same group + same dimension
      var gr = new GlideRecord('x_illu2_illumio_illumio_label_filter_item');
      gr.addQuery('sync_filter_group', current.getValue('sync_filter_group'));
      gr.addQuery('label_dimension', current.getValue('label_dimension'));
      gr.addQuery('sys_id', '!=', current.getUniqueValue());
      gr.setLimit(1);
      gr.query();

      if (gr.next()) {
          var groupName = current.sync_filter_group.getDisplayValue() || 'this group';
          var dimensionName = current.label_dimension.getDisplayValue() || 'this dimension';

          gs.addErrorMessage(
              'Duplicate Label Dimension: "' + dimensionName + '" already exists in group "' + groupName + '". ' +
              'Each label dimension can only appear once per group. ' +
              'To filter by multiple values of the same dimension, create separate groups.'
          );
		  current.label_dimension.setError('This dimension already exists in the selected group.');
          current.setAbortAction(true);
      }
  })(current, previous);
